local Component=require(script.Parent.Parent.Base.Component)
return function(ctx,messages,onSend) local f=Instance.new("Frame",ctx.Parent);f.Name="ChatBox";f.Size=UDim2.new(1,0,0,220);f.BackgroundColor3=ctx.Theme:Get("Surface");Instance.new("UICorner",f).CornerRadius=UDim.new(0,12);local list=Instance.new("ScrollingFrame",f);list.Position=UDim2.fromOffset(8,8);list.Size=UDim2.new(1,-16,1,-52);list.BackgroundTransparency=1;list.BorderSizePixel=0;list.AutomaticCanvasSize=Enum.AutomaticSize.Y;list.ScrollBarThickness=4;local ll=Instance.new("UIListLayout",list);ll.Padding=UDim.new(0,5);for _,m in ipairs(messages or {})do local l=Instance.new("TextLabel",list);l.Size=UDim2.new(1,0,0,28);l.BackgroundColor3=ctx.Theme:Get("SurfaceAlt");l.TextColor3=ctx.Theme:Get("Text");l.Text=tostring(m.Text or m[1] or m);l.Font=Enum.Font.Gotham;l.TextSize=12;l.TextXAlignment=Enum.TextXAlignment.Left;Instance.new("UICorner",l).CornerRadius=UDim.new(0,8);end;local input=Instance.new("TextBox",f);input.Position=UDim2.fromOffset(8,184);input.Size=UDim2.new(1,-90,0,30);input.BackgroundColor3=ctx.Theme:Get("SurfaceAlt");input.TextColor3=ctx.Theme:Get("Text");input.PlaceholderText="Message";input.Font=Enum.Font.Gotham;input.TextSize=12;Instance.new("UICorner",input).CornerRadius=UDim.new(0,8);local send=Instance.new("TextButton",f);send.Position=UDim2.new(1,-74,0,184);send.Size=UDim2.fromOffset(66,30);send.Text="Send";send.BackgroundColor3=ctx.Theme:Get("Accent");send.TextColor3=Color3.new(1,1,1);send.Font=Enum.Font.GothamBold;send.TextSize=12;Instance.new("UICorner",send).CornerRadius=UDim.new(0,8);ctx.Input:BindPress(send,function()if input.Text~="" then if onSend then onSend(input.Text)end;input.Text=""end end);return Component.new(f,ctx) end
